parameters.jsCode:
const prospects = [
  { company: 'MVP Bookkeeping', website: 'https://mvpbookkeeping.co.uk', region: 'Cornwall, UK', role: 'the practice owner' },
  { company: 'LVS Bookkeeping', website: 'https://lvsbookkeeping.co.uk', region: 'Wimborne, UK', role: 'the founder' },
  { company: 'A Touch Bookkeeping', website: 'https://atouchbookkeeping.co.uk', region: 'Witham, Essex, UK', role: 'the owner' },
  { company: 'Ledger Leaf Ltd', website: 'https://www.ledgerleafltd.com', region: 'Knaresborough, UK', role: 'the founder' },
  { company: 'Fair and Square Bookkeeping', website: 'https://www.fairandsquarebookkeeping.com', region: 'United States', role: 'the owner' }
];

const profile = $('Corvell Books profile').first().json;

return prospects.map(function (p) {
  return { json: Object.assign({}, profile, p) };
});

const wanted = ['about', 'our-story', 'meet', 'services', 'what-we-do', 'how-it-works', 'pricing'];
const items = $input.all();
const out = [];

for (let idx = 0; idx < items.length; idx++) {
  const item = items[idx];
  const src = $('Prospect list (edit me)').all()[idx].json;
  const data = item.json.data || {};
  const meta = data.metadata || {};
  const homeUrl = meta.sourceURL || meta.url || src.website || '';
  const homeText = data.markdown || '';
  const allLinks = Array.isArray(data.links) ? data.links.slice() : [];

  const parts = homeText.split('](');
  for (let i = 1; i < parts.length; i++) {
    const inside = parts[i].split(')')[0];
    if (inside && inside.indexOf('http') === 0) allLinks.push(inside);
  }

  let secondUrl = '';
  let bestRank = 999;
  for (const link of allLinks) {
    const lower = String(link).toLowerCase();
    for (let w = 0; w < wanted.length; w++) {
      if (lower.indexOf('/' + wanted[w]) > -1 && w < bestRank) {
        bestRank = w;
        secondUrl = link;
      }
    }
  }
  if (secondUrl === homeUrl) secondUrl = '';

  out.push({ json: {
    company: src.company,
    website: src.website,
    region: src.region,
    role: src.role,
    product: src.product,
    idealCustomer: src.idealCustomer,
    painPoints: src.painPoints,
    offer: src.offer,
    sender: src.sender,
    tone: src.tone,
    demoInbox: src.demoInbox,
    telegramChatId: src.telegramChatId,
    homeUrl: homeUrl,
    homeText: homeText,
    secondUrl: secondUrl || homeUrl
  }, pairedItem: { item: idx } });
}

return out;

const picked = $('Find the about or services page').all();
const scraped = $input.all();
const nl = String.fromCharCode(10, 10);
const out = [];

for (let i = 0; i < picked.length; i++) {
  const a = picked[i].json;
  const b = scraped[i] && scraped[i].json ? (scraped[i].json.data || {}) : {};
  const bMeta = b.metadata || {};
  const bText = b.markdown || '';
  const extra = bText && bMeta.sourceURL !== a.homeUrl ? bText : '';
  const siteText = (a.homeText + nl + '--- SECOND PAGE ---' + nl + extra).slice(0, 7000);

  out.push({ json: {
    company: a.company,
    website: a.website,
    region: a.region,
    role: a.role,
    product: a.product,
    idealCustomer: a.idealCustomer,
    painPoints: a.painPoints,
    offer: a.offer,
    sender: a.sender,
    tone: a.tone,
    demoInbox: a.demoInbox,
    telegramChatId: a.telegramChatId,
    pagesRead: extra ? 2 : 1,
    siteText: siteText
  }, pairedItem: { item: i } });
}

return out;

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "companySummary": {
      "type": "string",
      "description": "What the company is, in one sentence, from their own site"
    },
    "whatTheySell": {
      "type": "string",
      "description": "Their services, in their language"
    },
    "customerType": {
      "type": "string",
      "description": "Who they serve, or not stated"
    },
    "teamSize": {
      "type": "string",
      "description": "Team size if the site says it, otherwise not stated"
    },
    "signals": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Two or three signs they need bookkeeping software, each tied to something on the site"
    },
    "hook": {
      "type": "string",
      "description": "One specific detail from their own words, usable as the first line of an email"
    },
    "fitScore": {
      "type": "integer",
      "minimum": 1,
      "maximum": 10,
      "description": "Fit for Corvell Books, 10 = definitely does bookkeeping at volume"
    },
    "fitReason": {
      "type": "string",
      "description": "Why that score, in one or two sentences"
    },
    "emailSubject": {
      "type": "string",
      "description": "Subject line, under 60 characters, no hype"
    },
    "emailPlain": {
      "type": "string",
      "description": "Plain text email body, paragraphs separated by blank lines, no subject line, max 120 words"
    }
  },
  "required": [
    "companySummary",
    "whatTheySell",
    "customerType",
    "teamSize",
    "signals",
    "hook",
    "fitScore",
    "fitReason",
    "emailSubject",
    "emailPlain"
  ]
}

